                marks.setdefault(c, []).append((r, color))

    for c, points in marks.items():
        points.sort()
        # Each gap extends vertically to the neighboring horizontal bars.
        for i, (r, color) in enumerate(points):
            top = points[i - 1][0] + 1 if i else 0
            for rr in range(top, r + 1):
                out[rr][c] = color

        # If a vertical colored marker continues below the last bar, preserve it.
        last_r = points[-1][0]
        below = [grid[rr][c] for rr in range(last_r + 1, h) if grid[rr][c] != 0]
        if below:
            color = below[0]
            for rr in range(last_r + 1, h):
                out[rr][c] = color

    return out
